// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, uint256 times) public {
        // keep the domain admissible: amounts within a fundable range,
        // a bounded number of deposits
        amount = bound(amount, 1, 1 ether);
        times = bound(times, 1, 20);

        vm.deal(address(this), amount * times);

        for (uint256 i = 0; i < times; i++) {
            (bool ok, ) = address(c).call{value: amount}("");
            assertTrue(ok, "deposit must succeed");
        }

        // Rule: each accepted deposit adds exactly one to depositsCount,
        // independent of the deposit amount.
        assertEq(c.depositsCount(), times);
    }
}
